INSERT INTO public.ai_resolution_rules (id, prediction_type, truth_table, truth_column, subject_column, truth_aggregate, window_days, date_column, resolution_mode, verdict_weight, tolerance_pct, rationale, enabled, created_at) VALUES (1, 'yield_qtl', 'yield_actuals', 'quantity_harvested_kg', 'farmer_id', 'sum', 180, 'harvested_on', 'observed', 1.00, 15.00, 'Harvest is weighed and recorded in yield_actuals. The scale is the judge; no human needed.', true, '2026-09-05 14:07:02.231475') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_resolution_rules (id, prediction_type, truth_table, truth_column, subject_column, truth_aggregate, window_days, date_column, resolution_mode, verdict_weight, tolerance_pct, rationale, enabled, created_at) VALUES (2, 'farmer_revenue', 'farmer_revenue', 'gross_amount', 'farmer_id', 'sum', 90, 'received_on', 'observed', 1.00, 10.00, 'Money received is money received. Fully autonomous.', true, '2026-09-05 14:07:02.231475') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_resolution_rules (id, prediction_type, truth_table, truth_column, subject_column, truth_aggregate, window_days, date_column, resolution_mode, verdict_weight, tolerance_pct, rationale, enabled, created_at) VALUES (3, 'order_value', 'orders', 'total_amount', 'id', 'first', NULL, NULL, 'observed', 1.00, 5.00, 'The order settles at a number. Direct comparison, fully autonomous.', true, '2026-09-05 14:07:02.231475') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_resolution_rules (id, prediction_type, truth_table, truth_column, subject_column, truth_aggregate, window_days, date_column, resolution_mode, verdict_weight, tolerance_pct, rationale, enabled, created_at) VALUES (4, 'delivery_days', 'orders', 'actual_delivery_date', 'id', 'first', NULL, NULL, 'observed', 1.00, 20.00, 'Resolved against orders.actual_delivery_date. Wide tolerance because NE road conditions add variance no forecaster can own. Note this resolves on the ORDER, not shipments — shipments has no realised-duration column.', true, '2026-09-05 14:07:02.231475') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_resolution_rules (id, prediction_type, truth_table, truth_column, subject_column, truth_aggregate, window_days, date_column, resolution_mode, verdict_weight, tolerance_pct, rationale, enabled, created_at) VALUES (5, 'quality_pass', 'quality_checks', 'check_status', 'project_id', 'last', 30, 'check_date', 'observed', 1.00, 0.00, 'A check either passed or it did not. Categorical, zero tolerance. Keyed on project_id because quality_checks has no batch/lot column — see the disabled rules below for what that costs us.', true, '2026-09-05 14:07:02.231475') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_resolution_rules (id, prediction_type, truth_table, truth_column, subject_column, truth_aggregate, window_days, date_column, resolution_mode, verdict_weight, tolerance_pct, rationale, enabled, created_at) VALUES (6, 'transaction_settled', 'transactions', 'status', 'id', 'last', 60, 'created_at', 'observed', 1.00, 0.00, 'Terminal transaction status is directly observable.', true, '2026-09-05 14:07:02.231475') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_resolution_rules (id, prediction_type, truth_table, truth_column, subject_column, truth_aggregate, window_days, date_column, resolution_mode, verdict_weight, tolerance_pct, rationale, enabled, created_at) VALUES (7, 'coldchain_spoilage_prevented', 'quality_checks', 'check_status', 'project_id', 'last', 14, 'check_date', 'proxy', 0.60, 0.00, 'BLOCKED: quality_checks cannot be keyed to a batch, so a quarantined batch cannot be followed to its later result. Also COUNTERFACTUAL — the batch was quarantined, so the spoilage it would have suffered never happened and is not measurable even in principle. Proxy weight 0.60 once a batch link exists.', false, '2026-09-05 14:07:02.231475') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_resolution_rules (id, prediction_type, truth_table, truth_column, subject_column, truth_aggregate, window_days, date_column, resolution_mode, verdict_weight, tolerance_pct, rationale, enabled, created_at) VALUES (8, 'fraud_flag', 'transactions', 'status', 'id', 'last', 60, 'created_at', 'proxy', 0.50, 0.00, 'DISABLED DELIBERATELY, not blocked. A held transaction cannot complete, so the fraud it would have caused is unobservable. Scoring a fraud model on the transactions it blocked is a self-confirming loop: it reports excellent accuracy forever while learning nothing. Enable only alongside an external chargeback or confirmed-bad-account feed.', false, '2026-09-05 14:07:02.231475') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_resolution_rules (id, prediction_type, truth_table, truth_column, subject_column, truth_aggregate, window_days, date_column, resolution_mode, verdict_weight, tolerance_pct, rationale, enabled, created_at) VALUES (9, 'conflict_route_risk', 'shipments', 'status', 'id', 'first', 30, 'created_at', 'human_only', 1.00, 25.00, 'Road-blockage risk during NE community tensions. If the route was changed the original road was never driven; if it was not changed, a safe arrival does not prove the risk was absent. Being wrong in the unsafe direction can put a driver in danger, so the standard of evidence is a person, not a proxy.', false, '2026-09-05 14:07:02.231475') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_resolution_rules (id, prediction_type, truth_table, truth_column, subject_column, truth_aggregate, window_days, date_column, resolution_mode, verdict_weight, tolerance_pct, rationale, enabled, created_at) VALUES (10, 'farmer_credit_risk', 'v_farmer_repayment_signal', 'on_time_score', 'farmer_id', 'avg', 180, 'due_date', 'proxy', 0.65, 25.00, 'farmerCreditRiskScore() (financialService.js) predicts a 0-100 creditworthiness score built from FDI, past repayment, farmer_revenue payment history and order track record. Resolved against AVG(on_time_score) over EMIs actually due in the 180 days after the prediction — real repayment behaviour, not a self-report. Proxy because the predicted number is a composite score, not literally a repayment percentage, so a close match is directional evidence, not identity. A farmer with no EMIs due in the window yields no_truth_yet, same as any other rule here — it does not resolve as a false pass.', true, '2026-09-05 14:07:40.084702') ON CONFLICT DO NOTHING;
