INSERT INTO public.defense_fitness_standards (id, force_name, category, gender, test_component, threshold_value, threshold_type, unit, notes, source_url, last_verified_date, created_at) VALUES ('d1fe9bfd-8006-4cae-989d-edacce92d72e', 'Indian Army (Agniveer GD)', 'army_agniveer_gd', 'any', 'run_1.6km', 330.00, 'max_time_seconds', 'seconds', 'Finishing within 5 min 30 sec earns maximum marks for the 1.6km run component of the PFT.', 'https://testbook.com/indian-army-agniveer/physical-fitness-test', '2026-08-16', '2026-09-05 14:07:06.273555') ON CONFLICT DO NOTHING;
INSERT INTO public.defense_fitness_standards (id, force_name, category, gender, test_component, threshold_value, threshold_type, unit, notes, source_url, last_verified_date, created_at) VALUES ('e5d6d7dd-c1b6-446b-8809-be89f7c2f510', 'Indian Army (Agniveer GD)', 'army_agniveer_gd', 'any', 'run_1.6km_disqualify', 345.00, 'max_time_seconds', 'seconds', 'Candidates taking longer than 5 min 45 sec are generally disqualified from the running event. PFT also includes pull-ups, a 9-feet ditch jump, and a zig-zag balance test (qualifying, not scored here).', 'https://testbook.com/indian-army-agniveer/physical-fitness-test', '2026-08-16', '2026-09-05 14:07:06.273555') ON CONFLICT DO NOTHING;
INSERT INTO public.defense_fitness_standards (id, force_name, category, gender, test_component, threshold_value, threshold_type, unit, notes, source_url, last_verified_date, created_at) VALUES ('44dbea4c-61fb-455d-9653-92f5847e2c69', 'BSF Constable GD', 'bsf_constable_gd', 'male', 'run_1.6km', NULL, 'max_time_seconds', 'seconds', 'PET running distance for male candidates is 1.6km. Exact time threshold varies by recruitment cycle — check the official BSF notification for the current cutoff.', 'https://rojgardekho.in/article/bsf-physical-test-2026', '2026-08-16', '2026-09-05 14:07:06.273555') ON CONFLICT DO NOTHING;
INSERT INTO public.defense_fitness_standards (id, force_name, category, gender, test_component, threshold_value, threshold_type, unit, notes, source_url, last_verified_date, created_at) VALUES ('94b5a9e7-aac4-475a-a860-e570afd63663', 'BSF Constable GD', 'bsf_constable_gd', 'female', 'run_800m', NULL, 'max_time_seconds', 'seconds', 'PET running distance for female candidates is 800m. Exact time threshold varies by recruitment cycle — check the official BSF notification for the current cutoff.', 'https://rojgardekho.in/article/bsf-physical-test-2026', '2026-08-16', '2026-09-05 14:07:06.273555') ON CONFLICT DO NOTHING;
INSERT INTO public.defense_fitness_standards (id, force_name, category, gender, test_component, threshold_value, threshold_type, unit, notes, source_url, last_verified_date, created_at) VALUES ('b30c6bb9-0a0b-4cef-9aa2-1996348f46e7', 'Delhi Police Constable', 'delhi_police_constable', 'male', 'height_cm', 170.00, 'min_value', 'cm', 'Minimum height for general category male candidates. Reserved categories and hill-area candidates may get relaxation per official rules.', 'https://devdefenceacademy.in/delhi-police-constable-physical-test/', '2026-08-16', '2026-09-05 14:07:06.273555') ON CONFLICT DO NOTHING;
