INSERT INTO public.wellness_natural_practices (id, practice_name, category, common_name, botanical_name, traditional_use, related_product_tags, evidence_level, requires_consultation, contraindications, source_reference, created_at, updated_at) VALUES ('e224b2c4-fb8c-4a8e-9963-f7a92b9dac23', 'Turmeric / Curcumin', 'herbal', 'Turmeric', 'Curcuma longa', 'Used traditionally as a culinary spice and in Ayurvedic practice to support digestion; its active compound curcumin has been studied for inflammatory and joint conditions.', '{spices,turmeric,curcumin}', 'preliminary_evidence', true, 'May interact with blood-thinning medication; high doses can cause GI upset. Avoid therapeutic doses during pregnancy without medical guidance.', 'NCCIH herb factsheet (Turmeric); trials registered on ClinicalTrials.gov', '2026-09-05 14:04:11.213613', '2026-09-05 14:04:11.213613') ON CONFLICT DO NOTHING;
INSERT INTO public.wellness_natural_practices (id, practice_name, category, common_name, botanical_name, traditional_use, related_product_tags, evidence_level, requires_consultation, contraindications, source_reference, created_at, updated_at) VALUES ('eb90cf40-468a-44f4-ba09-3729f77a1f9e', 'Ginger', 'herbal', 'Ginger', 'Zingiber officinale', 'Traditionally used to ease digestive discomfort and nausea.', '{spices,ginger}', 'well_established', false, 'Can interact with anticoagulant medication at high doses.', 'NCCIH herb factsheet (Ginger)', '2026-09-05 14:04:11.213613', '2026-09-05 14:04:11.213613') ON CONFLICT DO NOTHING;
INSERT INTO public.wellness_natural_practices (id, practice_name, category, common_name, botanical_name, traditional_use, related_product_tags, evidence_level, requires_consultation, contraindications, source_reference, created_at, updated_at) VALUES ('dae70ceb-77b2-4def-ae9a-e07610a26e4a', 'Tulsi (Holy Basil)', 'ayurveda', 'Tulsi', 'Ocimum tenuiflorum', 'Used in Ayurvedic tradition as a daily tea/adaptogen for general wellness and stress support.', '{herbal-tea,tulsi}', 'traditional_use', true, 'Limited human trial data; avoid therapeutic doses in pregnancy and alongside blood-sugar or blood-thinning medication without medical guidance.', 'Traditional Ayurvedic pharmacopoeia; preliminary human studies only', '2026-09-05 14:04:11.213613', '2026-09-05 14:04:11.213613') ON CONFLICT DO NOTHING;
INSERT INTO public.wellness_natural_practices (id, practice_name, category, common_name, botanical_name, traditional_use, related_product_tags, evidence_level, requires_consultation, contraindications, source_reference, created_at, updated_at) VALUES ('c35af94c-150d-4291-b13b-9580b1bf1e2d', 'Ashwagandha', 'ayurveda', 'Ashwagandha', 'Withania somnifera', 'Used in Ayurveda as a rasayana (rejuvenative) herb, commonly for stress and sleep support.', '{ayurveda,ashwagandha}', 'preliminary_evidence', true, 'Not recommended in pregnancy; may interact with thyroid, sedative, and immunosuppressant medication.', 'NCCIH herb factsheet (Ashwagandha); small-scale RCTs on stress/sleep outcomes', '2026-09-05 14:04:11.213613', '2026-09-05 14:04:11.213613') ON CONFLICT DO NOTHING;
INSERT INTO public.wellness_natural_practices (id, practice_name, category, common_name, botanical_name, traditional_use, related_product_tags, evidence_level, requires_consultation, contraindications, source_reference, created_at, updated_at) VALUES ('a16f073a-f400-4b78-b9b2-ecda0c67213f', 'Moringa', 'nutrition_therapy', 'Moringa', 'Moringa oleifera', 'Leaves used traditionally as a nutrient-dense food source, rich in vitamins and minerals.', '{moringa,superfood}', 'preliminary_evidence', false, 'May lower blood sugar; caution if on diabetes medication.', 'Nutritional composition studies; limited clinical trial data', '2026-09-05 14:04:11.213613', '2026-09-05 14:04:11.213613') ON CONFLICT DO NOTHING;
INSERT INTO public.wellness_natural_practices (id, practice_name, category, common_name, botanical_name, traditional_use, related_product_tags, evidence_level, requires_consultation, contraindications, source_reference, created_at, updated_at) VALUES ('af0c6a5c-ea81-404b-a47e-4d3c9edb42eb', 'Fenugreek', 'nutrition_therapy', 'Fenugreek', 'Trigonella foenum-graecum', 'Seeds used traditionally in cooking and, in some communities, to support lactation and blood-sugar balance.', '{spices,fenugreek}', 'preliminary_evidence', true, 'Can lower blood sugar and interact with diabetes/anticoagulant medication; avoid medicinal doses in pregnancy.', 'NCCIH herb factsheet (Fenugreek); small clinical studies on glycemic response', '2026-09-05 14:04:11.213613', '2026-09-05 14:04:11.213613') ON CONFLICT DO NOTHING;
INSERT INTO public.wellness_natural_practices (id, practice_name, category, common_name, botanical_name, traditional_use, related_product_tags, evidence_level, requires_consultation, contraindications, source_reference, created_at, updated_at) VALUES ('03ab59b9-c541-4880-8c4c-e55315e944bf', 'Amla (Indian Gooseberry)', 'nutrition_therapy', 'Amla', 'Phyllanthus emblica', 'Traditionally consumed as a food source of vitamin C and as an Ayurvedic rasayana.', '{amla,vitamin-c}', 'traditional_use', false, 'Generally recognized as safe as a food; therapeutic-dose evidence is limited.', 'Traditional Ayurvedic pharmacopoeia; nutritional composition data', '2026-09-05 14:04:11.213613', '2026-09-05 14:04:11.213613') ON CONFLICT DO NOTHING;
INSERT INTO public.wellness_natural_practices (id, practice_name, category, common_name, botanical_name, traditional_use, related_product_tags, evidence_level, requires_consultation, contraindications, source_reference, created_at, updated_at) VALUES ('8646a1e2-3b93-43bb-8e4c-16e39d29727c', 'Northeast Indian Forest Honey', 'traditional_practice', 'Wild/Forest Honey (NE India)', 'Apis dorsata / Apis cerana', 'Raw, unprocessed honey sourced from forests of Northeast India is traditionally used across the region as a home remedy for soothing coughs and sore throats, and as a natural sweetener believed to carry regional floral antimicrobial properties. This is traditional/folk use, not a clinically validated treatment for any specific condition.', '{honey,raw_honey,forest_honey,ne_produce}', 'traditional_use', true, 'Not recommended for infants under 12 months (botulism spore risk in raw honey). Diabetics should consult a physician before regular use due to sugar content. Not a substitute for medical treatment of persistent respiratory symptoms.', 'Regional folk-medicine knowledge, Northeast India; general honey-safety guidance (infant botulism risk) is well-established public health knowledge, not specific to this product.', '2026-09-05 14:07:05.629518', '2026-09-05 14:07:05.629518') ON CONFLICT DO NOTHING;
