INSERT INTO public.landed_cost_components (id, corridor, sequence_no, component, min_inr_per_kg, optimised_inr_per_kg, max_inr_per_kg, controllable, subsidy_scheme, notes, data_provenance, source_document, as_of) VALUES (1, 'NE->NCR', 1, 'Procurement farmgate (incl. local transport to aggregation)', 95.00, 100.00, 115.00, true, NULL, 'The largest line by far — roughly 83% of optimised landed cost. Also the one the platform least wants to reduce, since paying the farmer more is the point.', 'estimated', 'NE_Harvest_Complete_Business_Report.html', '2026-09-05') ON CONFLICT DO NOTHING;
INSERT INTO public.landed_cost_components (id, corridor, sequence_no, component, min_inr_per_kg, optimised_inr_per_kg, max_inr_per_kg, controllable, subsidy_scheme, notes, data_provenance, source_document, as_of) VALUES (2, 'NE->NCR', 2, 'Rail freight post NE Logistics Policy subsidy', 3.00, 4.00, 5.00, true, 'NE Logistics Policy Freight Subsidy', 'Already net of a 30-50% subsidy. Without the subsidy this line roughly doubles.', 'estimated', 'NE_Harvest_Complete_Business_Report.html', '2026-09-05') ON CONFLICT DO NOTHING;
INSERT INTO public.landed_cost_components (id, corridor, sequence_no, component, min_inr_per_kg, optimised_inr_per_kg, max_inr_per_kg, controllable, subsidy_scheme, notes, data_provenance, source_document, as_of) VALUES (3, 'NE->NCR', 3, 'Loading/unloading handling', 1.00, 1.50, 2.00, true, NULL, NULL, 'estimated', 'NE_Harvest_Complete_Business_Report.html', '2026-09-05') ON CONFLICT DO NOTHING;
INSERT INTO public.landed_cost_components (id, corridor, sequence_no, component, min_inr_per_kg, optimised_inr_per_kg, max_inr_per_kg, controllable, subsidy_scheme, notes, data_provenance, source_document, as_of) VALUES (4, 'NE->NCR', 4, 'Multi-layer insurance (transit + cold chain + cargo)', 0.30, 0.50, 0.80, true, NULL, 'Cheap relative to what it covers. Cutting it to save 50 paise is a false economy against a consignment worth over Rs 100/kg.', 'estimated', 'NE_Harvest_Complete_Business_Report.html', '2026-09-05') ON CONFLICT DO NOTHING;
INSERT INTO public.landed_cost_components (id, corridor, sequence_no, component, min_inr_per_kg, optimised_inr_per_kg, max_inr_per_kg, controllable, subsidy_scheme, notes, data_provenance, source_document, as_of) VALUES (5, 'NE->NCR', 5, 'Cold storage (origin + Delhi buffer)', 2.50, 3.50, 5.00, true, 'MIDH Horticulture Mission', NULL, 'estimated', 'NE_Harvest_Complete_Business_Report.html', '2026-09-05') ON CONFLICT DO NOTHING;
INSERT INTO public.landed_cost_components (id, corridor, sequence_no, component, min_inr_per_kg, optimised_inr_per_kg, max_inr_per_kg, controllable, subsidy_scheme, notes, data_provenance, source_document, as_of) VALUES (6, 'NE->NCR', 6, 'Losses/wastage (with cold chain: 4-8%)', 4.00, 6.00, 9.00, true, NULL, 'Stated as achievable WITH cold chain. Without it, NE horticulture losses run far higher and this line alone can exceed the freight it was meant to save.', 'estimated', 'NE_Harvest_Complete_Business_Report.html', '2026-09-05') ON CONFLICT DO NOTHING;
INSERT INTO public.landed_cost_components (id, corridor, sequence_no, component, min_inr_per_kg, optimised_inr_per_kg, max_inr_per_kg, controllable, subsidy_scheme, notes, data_provenance, source_document, as_of) VALUES (7, 'NE->NCR', 7, 'Last-mile delivery RWA (own reefer vehicle)', 2.00, 2.50, 3.00, true, NULL, 'Own reefer at Rs 2-3/kg against Rs 35-60/kg quick-commerce commission. The single largest structural cost advantage in the model.', 'estimated', 'NE_Harvest_Complete_Business_Report.html', '2026-09-05') ON CONFLICT DO NOTHING;
INSERT INTO public.landed_cost_components (id, corridor, sequence_no, component, min_inr_per_kg, optimised_inr_per_kg, max_inr_per_kg, controllable, subsidy_scheme, notes, data_provenance, source_document, as_of) VALUES (8, 'NE->NCR', 8, 'Platform overhead (tech + ops)', 2.00, 3.00, 4.00, true, NULL, NULL, 'estimated', 'NE_Harvest_Complete_Business_Report.html', '2026-09-05') ON CONFLICT DO NOTHING;
