INSERT INTO public.motion_presets (id, preset_key, category, duration_ms, easing, description, reduced_motion_duration_ms, reduced_motion_behaviour) VALUES (1, 'fade_in', 'transition', 180, 'ease-out', 'Element appears', 0, 'Appears immediately, no fade') ON CONFLICT DO NOTHING;
INSERT INTO public.motion_presets (id, preset_key, category, duration_ms, easing, description, reduced_motion_duration_ms, reduced_motion_behaviour) VALUES (2, 'slide_panel', 'page', 240, 'cubic-bezier(0.2,0,0,1)', 'Panel slides in from edge', 0, 'Panel appears in place. Large sliding movement is the main trigger for motion sickness.') ON CONFLICT DO NOTHING;
INSERT INTO public.motion_presets (id, preset_key, category, duration_ms, easing, description, reduced_motion_duration_ms, reduced_motion_behaviour) VALUES (3, 'button_press', 'micro_interaction', 90, 'ease-out', 'Button depresses on press', 60, 'Colour change only, no scale. Retains the feedback without the movement.') ON CONFLICT DO NOTHING;
INSERT INTO public.motion_presets (id, preset_key, category, duration_ms, easing, description, reduced_motion_duration_ms, reduced_motion_behaviour) VALUES (4, 'success_check', 'feedback', 420, 'ease-out', 'Checkmark draws in', 0, 'Checkmark shown complete. The confirmation matters; the drawing does not.') ON CONFLICT DO NOTHING;
INSERT INTO public.motion_presets (id, preset_key, category, duration_ms, easing, description, reduced_motion_duration_ms, reduced_motion_behaviour) VALUES (5, 'skeleton_pulse', 'loading', 1000, 'ease-in-out', 'Skeleton screen shimmer', 0, 'Static skeleton. A pulsing placeholder over a slow connection is a distraction, not information.') ON CONFLICT DO NOTHING;
INSERT INTO public.motion_presets (id, preset_key, category, duration_ms, easing, description, reduced_motion_duration_ms, reduced_motion_behaviour) VALUES (6, 'toast_enter', 'feedback', 200, 'ease-out', 'Toast slides up', 0, 'Toast appears in place') ON CONFLICT DO NOTHING;
INSERT INTO public.motion_presets (id, preset_key, category, duration_ms, easing, description, reduced_motion_duration_ms, reduced_motion_behaviour) VALUES (7, 'progress_ring', 'micro_interaction', 600, 'linear', 'Circular progress', 600, 'Retained — this animation IS the information, not decoration. Removing it would leave no indication that anything is happening.') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_model_registry (id, model_key, display_name, provider, model_identifier, capabilities, context_window_tokens, supports_vision, supports_tools, supports_streaming, cost_per_1k_input_inr, cost_per_1k_output_inr, typical_latency_ms, data_residency, approved_for_pii, enabled, added_on, notes) VALUES (1, 'slot_reasoning_primary', 'Primary reasoning slot', 'UNASSIGNED', NULL, '{reasoning,long_context,quantitative}', NULL, false, true, false, NULL, NULL, NULL, 'unknown', false, false, '2026-09-05', 'Serves scheme_eligibility, price_forecast, contract_review, credit_assessment. Assign a model, set data_residency, then enable. Handles PII — residency must be answered before approved_for_pii can be set.') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_model_registry (id, model_key, display_name, provider, model_identifier, capabilities, context_window_tokens, supports_vision, supports_tools, supports_streaming, cost_per_1k_input_inr, cost_per_1k_output_inr, typical_latency_ms, data_residency, approved_for_pii, enabled, added_on, notes) VALUES (2, 'slot_vision', 'Vision slot', 'UNASSIGNED', NULL, '{vision,classification,ocr}', NULL, true, false, false, NULL, NULL, NULL, 'unknown', false, false, '2026-09-05', 'Serves crop_disease_detection, quality_grading, document_ocr. Note that OCR of land records and lab reports carries PII even though the image itself looks anonymous.') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_model_registry (id, model_key, display_name, provider, model_identifier, capabilities, context_window_tokens, supports_vision, supports_tools, supports_streaming, cost_per_1k_input_inr, cost_per_1k_output_inr, typical_latency_ms, data_residency, approved_for_pii, enabled, added_on, notes) VALUES (3, 'slot_multilingual', 'Multilingual advisory slot', 'UNASSIGNED', NULL, '{reasoning,multilingual}', NULL, false, false, false, NULL, NULL, NULL, 'unknown', false, false, '2026-09-05', 'Serves farmer_advisory. Must handle Assamese, Meitei, Khasi, Mizo, Nagamese and Bengali — an advisory in a language the farmer cannot read is not an advisory.') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_model_registry (id, model_key, display_name, provider, model_identifier, capabilities, context_window_tokens, supports_vision, supports_tools, supports_streaming, cost_per_1k_input_inr, cost_per_1k_output_inr, typical_latency_ms, data_residency, approved_for_pii, enabled, added_on, notes) VALUES (4, 'slot_coding', 'Code generation slot', 'UNASSIGNED', NULL, '{coding,long_context}', NULL, false, true, false, NULL, NULL, NULL, 'unknown', false, false, '2026-09-05', 'Serves code_generation. No PII by design — platform code should never carry it.') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_model_registry (id, model_key, display_name, provider, model_identifier, capabilities, context_window_tokens, supports_vision, supports_tools, supports_streaming, cost_per_1k_input_inr, cost_per_1k_output_inr, typical_latency_ms, data_residency, approved_for_pii, enabled, added_on, notes) VALUES (5, 'slot_retrieval', 'Retrieval slot', 'UNASSIGNED', NULL, '{retrieval,reasoning}', NULL, false, false, false, NULL, NULL, NULL, 'unknown', false, false, '2026-09-05', 'Serves knowledge_search. Backed by the platform SOP and documentation index.') ON CONFLICT DO NOTHING;
INSERT INTO public.ai_model_registry (id, model_key, display_name, provider, model_identifier, capabilities, context_window_tokens, supports_vision, supports_tools, supports_streaming, cost_per_1k_input_inr, cost_per_1k_output_inr, typical_latency_ms, data_residency, approved_for_pii, enabled, added_on, notes) VALUES (6, 'slot_local_fallback', 'On-premise fallback slot', 'UNASSIGNED', NULL, '{reasoning,multilingual}', NULL, false, false, false, NULL, NULL, NULL, 'on_premise', false, false, '2026-09-05', 'Deliberately on_premise. NE connectivity is intermittent, and an advisory layer that only works with a good uplink is unavailable exactly when a farmer is furthest from help. Also the only slot that can serve PII without an offshore transfer question.') ON CONFLICT DO NOTHING;
