INSERT INTO public.crop_value_compound_reference (id, variety_name, compound_key, typical_min, typical_max, unit, notes, source_type, source_url, last_verified_date, verified, verified_by, verified_at, created_at) VALUES ('972f5a7f-f714-4a07-b4a5-4dd68db25a70', 'Turmeric', 'CURCUMIN_PCT', 1.0000, 6.0000, '%', 'Raw/dried turmeric powder curcuminoid content typically 1-6% by weight; curcumin itself is ~70-75% of total curcuminoids. Varies by agro-climatic zone and processing.', 'published_study', 'https://pubmed.ncbi.nlm.nih.gov/17044766/', '2026-08-16', true, NULL, NULL, '2026-09-05 14:07:06.329464') ON CONFLICT DO NOTHING;
INSERT INTO public.crop_value_compound_reference (id, variety_name, compound_key, typical_min, typical_max, unit, notes, source_type, source_url, last_verified_date, verified, verified_by, verified_at, created_at) VALUES ('502170bf-bd5c-4b91-89ab-d12b7e9fa660', 'Bhut Jolokia (Ghost Pepper)', 'CAPSAICIN_SHU', 855000.0000, 1041427.0000, 'SHU', 'Guinness-certified peak measurement 1,001,304 SHU (2007); New Mexico State University Chile Pepper Institute study measured a range of 855,000-1,041,427 SHU (avg ~950,000), USDA ARS HPLC-tested.', 'institute', 'https://www.britannica.com/plant/ghost-pepper', '2026-08-16', true, NULL, NULL, '2026-09-05 14:07:06.329464') ON CONFLICT DO NOTHING;
INSERT INTO public.crop_value_compound_reference (id, variety_name, compound_key, typical_min, typical_max, unit, notes, source_type, source_url, last_verified_date, verified, verified_by, verified_at, created_at) VALUES ('cf605320-c2a8-4cbe-9fcf-38c423ac9217', 'Kashmiri Red Chilli', 'CAPSAICIN_SHU', 1000.0000, 2000.0000, 'SHU', 'Mild heat by chilli standards — the variety''s value is in color, not heat.', 'wikipedia', 'https://en.wikipedia.org/wiki/Kashmiri_red_chilli', '2026-08-16', true, NULL, NULL, '2026-09-05 14:07:06.329464') ON CONFLICT DO NOTHING;
INSERT INTO public.crop_value_compound_reference (id, variety_name, compound_key, typical_min, typical_max, unit, notes, source_type, source_url, last_verified_date, verified, verified_by, verified_at, created_at) VALUES ('2446054c-6858-428a-9c3f-d6de07b65de8', 'Kashmiri Red Chilli', 'ASTA_COLOR', 50.0000, 60.0000, 'ASTA', 'India Spices Board reports 54.10 ASTA for standard Kashmir chilli; premium graded lots can exceed 120 ASTA. This is the variety''s actual differentiator vs. heat-focused chillies.', 'trade_body', 'https://en.wikipedia.org/wiki/Kashmiri_red_chilli', '2026-08-16', true, NULL, NULL, '2026-09-05 14:07:06.329464') ON CONFLICT DO NOTHING;
