INSERT INTO public.markdown_rules (id, crop_key, applies_to_all, days_to_expiry_at_or_below, pct_unsold_at_or_above, discount_pct, never_below_floor, priority, enabled, rationale) VALUES (1, NULL, true, 7, 60.00, 10.00, true, 10, true, 'A week left with most of the lot unsold. Small nudge.') ON CONFLICT DO NOTHING;
INSERT INTO public.markdown_rules (id, crop_key, applies_to_all, days_to_expiry_at_or_below, pct_unsold_at_or_above, discount_pct, never_below_floor, priority, enabled, rationale) VALUES (2, NULL, true, 4, 50.00, 20.00, true, 20, true, 'Half unsold with four days left — clearance begins.') ON CONFLICT DO NOTHING;
INSERT INTO public.markdown_rules (id, crop_key, applies_to_all, days_to_expiry_at_or_below, pct_unsold_at_or_above, discount_pct, never_below_floor, priority, enabled, rationale) VALUES (3, NULL, true, 2, 30.00, 35.00, true, 30, true, 'Two days. Beyond this the alternative is not a lower price, it is a total loss plus disposal cost, so a deep discount is the better outcome for everyone including the farmer whose floor is still protected.') ON CONFLICT DO NOTHING;
INSERT INTO public.markdown_rules (id, crop_key, applies_to_all, days_to_expiry_at_or_below, pct_unsold_at_or_above, discount_pct, never_below_floor, priority, enabled, rationale) VALUES (4, NULL, true, 1, 10.00, 50.00, true, 40, true, 'Final day. Anything above the farmer floor beats writing the lot off.') ON CONFLICT DO NOTHING;
